{
  "implementation": "def solve(case):
    capacity = case['capacity']
    trials = case['trials']
    cache = {}
    order = []
    for idx, trial in enumerate(trials):
        sig = trial['signature']
        if sig in cache:
            cache[sig] = {
                'last_trial': idx,
                'reflection': trial['reflection'],
                'signature': sig,
                'success': trial['success']
            }
            order.remove(sig)
            order.append(sig)
        else:
            if len(cache) >= capacity:
                oldest = order.pop(0)
                del cache[oldest]
            cache[sig] = {
                'last_trial': idx,
                'reflection': trial['reflection'],
                'signature': sig,
                'success': trial['success']
            }
            order.append(sig)
    memory = [cache[sig] for sig in reversed(order)]
    signatures = [sig for sig in reversed(order)]
    return {'memory': memory, 'signatures': signatures}"
